import math

def solve(
    low: float,
    high: float,
    left: float,
    right: float,
) -> float:
    return uniform_probability(low,high,left,right)

def uniform_probability(low, high, left, right):
    overlap = max(0.0, min(high, right)-max(low, left))
    return overlap/(high-low)

