import math

def solve(
    values: list[float],
    probabilities: list[float],
) -> tuple[float, float]:
    return discrete_moments(values,probabilities)

def discrete_moments(values, probabilities):
    mean = sum(x*p for x,p in zip(values, probabilities))
    variance = sum(p*(x-mean)**2 for x,p in zip(values, probabilities))
    return mean, variance

p05-covariance:
import math

def solve(
    xs: list[float],
    ys: list[float],
) -> tuple[float, float, float, float, float]:
    return paired_statistics(xs,ys)

def paired_statistics(xs, ys):
    n = len(xs)
    mx, my = sum(xs)/n, sum(ys)/n
    vx = sum((x-mx)**2 for x in xs)/n
    vy = sum((y-my)**2 for y in ys)/n
    covariance = sum((x-mx)*(y-my) for x,y in zip(xs,ys))/n
    return mx, my, vx, vy, covariance

