p05-path:
import math

def solve(
    matrix: list[list[float]],
    initial_state: int,
    uniforms: list[float],
) -> list[int]:
    return path_from_uniforms(matrix,initial_state,uniforms)

def path_from_uniforms(matrix, initial_state, uniforms):
    states = [initial_state]
    for u in uniforms:
        cumulative = 0.0
        for j,p in enumerate(matrix[states[-1]]):
            cumulative += p
            if u < cumulative:
                states.append(j)
                break
        else:
            states.append(len(matrix)-1)
    return states

