import math

def solve(
    alpha: float,
    beta: float,
) -> list[float] | None:
    return stationary_two(alpha,beta)

def stationary_two(alpha, beta):
    if alpha+beta == 0:
        return None
    return [beta/(alpha+beta), alpha/(alpha+beta)]

p05-walk:
import math

def solve(
    probability: float,
    step_size: float,
    steps: int,
) -> tuple[list[float], list[float]]:
    return walk_moments(probability,step_size,steps)

def walk_moments(probability, step_size, steps):
    means = [n*step_size*(2*probability-1) for n in range(steps+1)]
    variances = [4*n*step_size**2*probability*(1-probability) for n in range(steps+1)]
    return means, variances

p05-bin-pairs:
import math

def solve(
    xs: list[float],
    ys: list[float],
    edges: list[float],
) -> list[list[int]]:
    return bin_pairs(xs,ys,edges)

def bin_pairs(xs, ys, edges):
    import bisect
    n = len(edges)-1
    counts = [[0]*n for _ in range(n)]
    for x,y in zip(xs,ys):
        i = min(bisect.bisect_right(edges,x)-1,n-1)
        j = min(bisect.bisect_right(edges,y)-1,n-1)
        counts[i][j] += 1
    return counts

